import{_ as a,o as e,c as i,aw as l}from"./chunks/framework.DLufY-ao.js";const s=JSON.parse('{"title":"HTTP/2","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/network/network/http/http2.md","filePath":"wiki/dev-commit/network/network/http/http2.md"}'),r={name:"wiki/dev-commit/network/network/http/http2.md"};function o(T,t,n,h,d,P){return e(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="http-2" tabindex="-1">HTTP/2 <a class="header-anchor" href="#http-2" aria-label="Permalink to &quot;HTTP/2&quot;">​</a></h1><h3 id="цели" tabindex="-1">Цели <a class="header-anchor" href="#цели" aria-label="Permalink to &quot;Цели&quot;">​</a></h3><ul><li>Добавить механизмы согласования протокола, клиент и сервер могут использовать HTTP 1.1, 2.0 или, гипотетически, иные, не HTTP-протоколы.</li><li>Поддержать совместимость с многими концепциями HTTP 1.1, например по набору методов доступа (GET, PUT, POST и т. п.), статусным кодам, формату URI, большому количеству заголовков</li><li>Уменьшение задержек доступа для ускорения загрузки страниц, в частности путём:</li><li>Сохранение совместимости с широко внедрёнными применениями HTTP, в том числе с веб-браузерами (полноценными и мобильными), API, используемыми в Интернете, веб-серверами, прокси-серверами, обратными прокси-серверами, сетями доставки контента</li></ul><h3 id="отличия-от-http-1-1" tabindex="-1">Отличия от HTTP/1.1 <a class="header-anchor" href="#отличия-от-http-1-1" aria-label="Permalink to &quot;Отличия от HTTP/1.1&quot;">​</a></h3><ul><li>Протокол HTTP/2 является бинарным. По сравнению с предыдущим стандартом изменены способы разбиения данных на фрагменты и транспортирования их между сервером и клиентом.</li><li>В HTTP/2 сервер имеет право послать то содержимое, которое ещё не было запрошено клиентом. Это позволит серверу сразу выслать дополнительные файлы, которые потребуются браузеру для отображения страниц, без необходимости анализа браузером основной страницы и запрашивания необходимых дополнений.</li><li>Также часть улучшений получена за счёт мультиплексирования запросов и ответов (для преодоления проблемы «head-of-line blocking» протоколов HTTP/1.x), а также за счёт сжатия передаваемых заголовков и введения явной приоритизации запросов.</li></ul><h3 id="шифрование" tabindex="-1">Шифрование <a class="header-anchor" href="#шифрование" aria-label="Permalink to &quot;Шифрование&quot;">​</a></h3><ul><li>HTTP/2 определён как для HTTP URI (то есть без шифрования), так и для HTTPS URI (поверх TLS 1.2 и выше).</li><li>Хотя стандарт определяет шифрование как необязательное[15], для большинства клиентских реализаций (Firefox[16], Chrome, Safari, Opera, IE, Edge) возможно использование HTTP/2 только поверх TLS.</li></ul>',7)])])}const p=a(r,[["render",o]]);export{s as __pageData,p as default};
